request.cmd:
perl -MJSON::PP -MEncode -MCwd=abs_path -MFile::Basename=dirname -e '
use strict; use warnings;
my $base="docs/papers211_215_sequence/scouting/finite_metric_reconstruction_scout01";
my %seen; my $total=0;
for my $name ("NATIVE_READS.json","BROWSER_READS.json") {
 open my $fh,"<:raw","$base/$name" or die "$name: $!";
 local $/; my $bytes=<$fh>; close $fh;
 my $obj=decode_json($bytes);
 die "missing records" unless ref($obj->{records}) eq "ARRAY";
 my $n=@{$obj->{records}}; die "record count $name" unless $n==11;
 for my $r (@{$obj->{records}}) {
  die "duplicate index" if $seen{$r->{capture_index}}++;
  die "missing request/result" unless exists $r->{request} && exists $r->{result};
  die "browser return shape" if $name eq "BROWSER_READS.json" && ref($r->{result});
  die "local return shape" if $name eq "NATIVE_READS.json" && ref($r->{result}) ne "HASH";
 }
 $total+=$n; print "$name: parsed $n actual captured records\n";
}
die "capture union" unless $total==22 && keys(%seen)==22;
for my $i (0..21) { die "missing index $i" unless exists $seen{$i}; }
my $links=0;
for my $name ("REPORT.md","PROOF_PACKAGE.md","SOURCE_READS.md") {
 open my $fh,"<:raw","$base/$name" or die "$name: $!";
 local $/; my $t=decode("UTF-8",scalar(<$fh>),FB_CROAK); close $fh;
 while ($t =~ /\]\(([^)]+)\)/g) {
  my $p=$1; next if $p =~ m{^https?://} || $p =~ /^#/;
  $p =~ s/#.*$//; die "missing local link $name: $p" unless -f "$base/$p";
  $links++;
 }
}
print "capture-index union: 22 unique consecutive records\n";
print "local Markdown file links: $links resolved\n";
'

